// aiditor.ui.colorInput - compact swatch + rich ARGB color picker.
//
// opts:
//   value:     string|int|array|signal   "#rrggbb", "#aarrggbb", 24-bit int, vec3, or vec4
//   onChange?: (v) => void
//   valueKind?: 'hex' | 'int' | 'vec3' | 'vec4'      (default 'hex')
