        state.valueFills.push(preview.querySelector('.aiditor-ui-color-preview-fill'))
        state.valueInputs.push({ kind: 'hex', el: hex.querySelector('input') })
        valueRow.appendChild(preview)
        valueRow.appendChild(hex)
