        ta.value = value.slice(0, range.start) + nextBlock + value.slice(range.end)
        ta.selectionStart = s === range.start ? s : s + 2
        ta.selectionEnd = n + lines * 2
        doWrite(ta.value); refreshGutter(); refreshHighlight()
        return
